&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;6nl7k-0-0&quot;&gt;&lt;span data-offset-key=&quot;6nl7k-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Experience with Sarbanes- Oxley compliance and internal controls&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
