&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;High school diploma or equivalency certificate&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335551550&amp;quot;:0,&amp;quot;335551620&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;3+ years sinker EDM programming experience&lt;/li&gt;
&lt;li&gt;1+ year experience CNC programming machining for electrodes&lt;/li&gt;
&lt;li&gt;1+ year of pulling or designing electrodes&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
