&lt;div class=&quot;flex w-full flex-col gap-1 empty:hidden first:pt-[3px]&quot;&gt;
&lt;p data-start=&quot;228&quot; data-end=&quot;563&quot;&gt;Als Schichtleiter Instandhaltung&lt;strong data-start=&quot;232&quot; data-end=&quot;280&quot;&gt;&amp;nbsp;(all genders)&lt;/strong&gt; übernimmst Du eine zentrale Rolle beim Aufbau unseres neuen &lt;strong data-start=&quot;341&quot; data-end=&quot;395&quot;&gt;Factor Produktionsstandorts in Verden an der Aller&lt;/strong&gt;. Du bist verantwortlich für die Organisation und Weiterentwicklung der technischen Instandhaltung sowie für die Koordination eines Technikteams im Zwei-Schichtbetrieb.&lt;/p&gt;
&lt;p data-start=&quot;565&quot; data-end=&quot;938&quot;&gt;Du stellst sicher, dass unsere Produktionsanlagen, Großküchengeräte und technischen Systeme zuverlässig betrieben, gewartet und kontinuierlich verbessert werden. Durch strukturierte Planung präventiver Wartungen,&lt;/p&gt;
&lt;h2 data-start=&quot;565&quot; data-end=&quot;938&quot;&gt;&lt;strong&gt;Dein Verantwortungsbereich&lt;/strong&gt;&lt;/h2&gt;
&lt;ul data-start=&quot;1126&quot; data-end=&quot;2190&quot;&gt;
&lt;li data-section-id=&quot;13cqpdh&quot; data-start=&quot;1126&quot; data-end=&quot;1262&quot;&gt;
&lt;p data-start=&quot;1128&quot; data-end=&quot;1262&quot;&gt;Du übernimmst die &lt;strong data-start=&quot;1146&quot; data-end=&quot;1202&quot;&gt;technische Verantwortung für den Produktionsstandort&lt;/strong&gt; und führst das Instandhaltungsteam im Zwei-Schichtbetrieb&lt;/p&gt;
&lt;/li&gt;
&lt;li data-section-id=&quot;17t2cmv&quot; data-start=&quot;1263&quot; data-end=&quot;1346&quot;&gt;
&lt;p data-start=&quot;1265&quot; data-end=&quot;1346&quot;&gt;Du organisierst und moderierst &lt;strong data-start=&quot;1296&quot; data-end=&quot;1344&quot;&gt;Start-of-Shift Meetings zur Tageszielplanung&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li data-section-id=&quot;mgjb81&quot; data-start=&quot;1347&quot; data-end=&quot;1474&quot;&gt;
&lt;p data-start=&quot;1349&quot; data-end=&quot;1474&quot;&gt;Du planst und koordinierst &lt;strong data-start=&quot;1376&quot; data-end=&quot;1408&quot;&gt;präventive Wartungsmaßnahmen&lt;/strong&gt;, sodass rund &lt;strong data-start=&quot;1422&quot; data-end=&quot;1472&quot;&gt;70 % der Aufgaben strukturiert vorgeplant sind&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li data-section-id=&quot;15tvv9f&quot; data-start=&quot;1475&quot; data-end=&quot;1592&quot;&gt;
&lt;p data-start=&quot;1477&quot; data-end=&quot;1592&quot;&gt;Du stellst die &lt;strong data-start=&quot;1492&quot; data-end=&quot;1583&quot;&gt;Betriebsbereitschaft von Produktionsanlagen, Großküchengeräten und technischen Systemen&lt;/strong&gt; sicher&lt;/p&gt;
&lt;/li&gt;
&lt;li data-section-id=&quot;111w6ap&quot; data-start=&quot;1593&quot; data-end=&quot;1682&quot;&gt;
&lt;p data-start=&quot;1595&quot; data-end=&quot;1682&quot;&gt;Du koordinierst &lt;strong data-start=&quot;1611&quot; data-end=&quot;1680&quot;&gt;Störungsbehebungen, Wartungsarbeiten und technische Optimierungen&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li data-section-id=&quot;rql6mi&quot; data-start=&quot;1683&quot; data-end=&quot;1781&quot;&gt;
&lt;p data-start=&quot;1685&quot; data-end=&quot;1781&quot;&gt;Du arbeitest eng mit &lt;strong data-start=&quot;1706&quot; data-end=&quot;1770&quot;&gt;Produktion, Qualität, Operations und externen Dienstleistern&lt;/strong&gt; zusammen&lt;/p&gt;
&lt;/li&gt;
&lt;li data-section-id=&quot;mwhn8v&quot; data-start=&quot;1782&quot; data-end=&quot;1888&quot;&gt;
&lt;p data-start=&quot;1784&quot; data-end=&quot;1888&quot;&gt;Du entwickelst und überwachst &lt;strong data-start=&quot;1814&quot; data-end=&quot;1886&quot;&gt;technische KPIs zur Anlagenverfügbarkeit und Instandhaltungsleistung&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li data-section-id=&quot;1gqwhtx&quot; data-start=&quot;1889&quot; data-end=&quot;1991&quot;&gt;
&lt;p data-start=&quot;1891&quot; data-end=&quot;1991&quot;&gt;Du identifizierst &lt;strong data-start=&quot;1909&quot; data-end=&quot;1989&quot;&gt;Verbesserungspotenziale in Wartung, Anlagenbetrieb und technischen Prozessen&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li data-section-id=&quot;19z2w5f&quot; data-start=&quot;1992&quot; data-end=&quot;2093&quot;&gt;
&lt;p data-start=&quot;1994&quot; data-end=&quot;2093&quot;&gt;Du unterstützt den &lt;strong data-start=&quot;2013&quot; data-end=&quot;2079&quot;&gt;Aufbau und die Weiterentwicklung der technischen Infrastruktur&lt;/strong&gt; am Standort&lt;/p&gt;
&lt;/li&gt;
&lt;li data-section-id=&quot;1iq4lqj&quot; data-start=&quot;2094&quot; data-end=&quot;2190&quot;&gt;
&lt;p data-start=&quot;2096&quot; data-end=&quot;2190&quot;&gt;Du stellst die &lt;strong data-start=&quot;2111&quot; data-end=&quot;2181&quot;&gt;Einhaltung von Arbeitssicherheits-, Umwelt- und Qualitätsstandards&lt;/strong&gt; sicher&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Dein Profil&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Technische Ausbildung im Bereich &lt;strong data-start=&quot;2247&quot; data-end=&quot;2316&quot;&gt;Mechatronik, Elektrotechnik, Kältetechnik oder Versorgungstechnik&lt;/strong&gt;, idealerweise ergänzt durch Meister- oder Technikerabschluss&lt;/li&gt;
&lt;li data-section-id=&quot;croh4l&quot; data-start=&quot;2380&quot; data-end=&quot;2474&quot;&gt;
&lt;p data-start=&quot;2382&quot; data-end=&quot;2474&quot;&gt;Mehrjährige Erfahrung in der &lt;strong data-start=&quot;2411&quot; data-end=&quot;2472&quot;&gt;Instandhaltung in Produktions- oder Lebensmittelbetrieben&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li data-section-id=&quot;1c6r2iq&quot; data-start=&quot;2475&quot; data-end=&quot;2542&quot;&gt;
&lt;p data-start=&quot;2477&quot; data-end=&quot;2542&quot;&gt;Erfahrung in der &lt;strong data-start=&quot;2494&quot; data-end=&quot;2540&quot;&gt;Koordination oder Führung von Technikteams&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li data-section-id=&quot;gtmy6e&quot; data-start=&quot;2543&quot; data-end=&quot;2643&quot;&gt;
&lt;p data-start=&quot;2545&quot; data-end=&quot;2643&quot;&gt;Kenntnisse in &lt;strong data-start=&quot;2559&quot; data-end=&quot;2624&quot;&gt;Kälte- und Klimatechnik sowie im Umgang mit Großküchengeräten&lt;/strong&gt; sind von Vorteil&lt;/p&gt;
&lt;/li&gt;
&lt;li data-section-id=&quot;1uc8h8i&quot; data-start=&quot;2644&quot; data-end=&quot;2728&quot;&gt;
&lt;p data-start=&quot;2646&quot; data-end=&quot;2728&quot;&gt;Erfahrung mit &lt;strong data-start=&quot;2660&quot; data-end=&quot;2726&quot;&gt;präventiver Instandhaltungsplanung und KPI-basierter Steuerung&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li data-section-id=&quot;gja07t&quot; data-start=&quot;2729&quot; data-end=&quot;2801&quot;&gt;
&lt;p data-start=&quot;2731&quot; data-end=&quot;2801&quot;&gt;Strukturierte Arbeitsweise sowie &lt;strong data-start=&quot;2764&quot; data-end=&quot;2799&quot;&gt;ausgeprägte Hands-on-Mentalität&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
