&lt;li style=&quot;font-weight: bold;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;strong&gt;Ermäßigte Fitnessangebote&lt;/strong&gt;&lt;/li&gt;
